package com.arjunren.bus;
import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import java.security.*;import java.util.*;
public final class PasswordService{private static final int ITERATIONS=210_000;public String hash(String password){if(password==null||password.length()<12)throw new IllegalArgumentException("Password must contain at least 12 characters");byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);return ITERATIONS+":"+Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(derive(password,salt,ITERATIONS));}public boolean verify(String password,String encoded){try{var p=encoded.split(":");var expected=Base64.getDecoder().decode(p[2]);return MessageDigest.isEqual(expected,derive(password,Base64.getDecoder().decode(p[1]),Integer.parseInt(p[0])));}catch(Exception e){return false;}}private byte[] derive(String password,byte[] salt,int iterations){try{var spec=new PBEKeySpec(password.toCharArray(),salt,iterations,256);return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}catch(Exception e){throw new IllegalStateException(e);}}}
